// Racer quad: thread a course of 5 gates as fast as possible, then hold at the last one.
// Same cascaded PID + quad mixer as drone-race.json; genome = its 9 gains + "lead" (how far past the current gate it aims).
// Reward terms:
//   gates    - +10 per gate passed (pass = within 3 m of the gate centre, in order)
//   time     - one-off when the last gate is passed: 2 points per second of episode left (faster = more)
//   progress - always-on penalty: distance to the next gate / 100 per second
//   hold     - seconds within 3 m of the last gate after finishing, slower than 3 m/s
//   upright, spin - small penalties (lean past 85 deg, yaw rate)
//   crash    - crash, flip or above 60 m: -2 per second of episode lost, -1
const GATES = [[25, 6, 0], [55, 12, 15], [85, 7, -12], [115, 15, 10], [145, 8, 0]];
function terms() { return ["gates", "time", "progress", "hold", "upright", "spin", "crash"]; }
function pos(i) { return { x: -i["target.dx"], y: 10 - i["target.dy"], z: -i["target.dz"] }; }
function aim(ctx) {
  const i = ctx.in, m = ctx.memory, p = pos(i), k = Math.min(m.gate || 0, GATES.length - 1), g = GATES[k];
  let tx = g[0], ty = g[1], tz = g[2];
  const lead = ctx.genome ? ctx.genome.get("lead") : 0;
  if (k + 1 < GATES.length && (m.gate || 0) < GATES.length) {   // aim a little past the gate, toward the next one
    const n = GATES[k + 1], d = Math.hypot(n[0] - g[0], n[1] - g[1], n[2] - g[2]);
    tx += (n[0] - g[0]) / d * lead; ty += (n[1] - g[1]) / d * lead; tz += (n[2] - g[2]) / d * lead;
  }
  return { dx: tx - p.x, dy: ty - p.y, dz: tz - p.z };
}
function reward(ctx) {
  const i = ctx.in, s = ctx.state, dt = ctx.dt, m = ctx.memory, p = pos(i);
  if (m.gate === undefined) m.gate = 0;
  let gates = 0, time = 0, dist = 0;
  if (m.gate < GATES.length) {
    const g = GATES[m.gate];
    dist = Math.hypot(g[0] - p.x, g[1] - p.y, g[2] - p.z);
    if (dist < 3) { m.gate++; gates = 10; if (m.gate === GATES.length) { m.tFinish = ctx.t; time = 2 * (ctx.info.duration - ctx.t); } }
  }
  const L = GATES[GATES.length - 1], dl = Math.hypot(L[0] - p.x, L[1] - p.y, L[2] - p.z);
  const speed = Math.sqrt(s.vx * s.vx + s.vy * s.vy + s.vz * s.vz);
  const lean = Math.sqrt(i["att.pitch"] * i["att.pitch"] + i["att.roll"] * i["att.roll"]);
  return {
    gates: gates, time: time,
    progress: m.gate < GATES.length ? -dist / 100 * dt : 0,
    hold: (m.gate >= GATES.length && dl < 3 && speed < 3) ? dt : 0,
    upright: lean > 85 ? -dt : 0,
    spin: -Math.min(Math.abs(i["rate.yaw"]) / 180, 1) * dt * 0.3,
  };
}
function failed(ctx) { const i = ctx.in; return ctx.state.crashed || Math.abs(i["att.roll"]) > 120 || i.alt > 60; }
function terminate(ctx) { return failed(ctx); }
function fitness(ctx) {
  const crash = failed(ctx) ? -2 * (ctx.info.duration - ctx.t) - 1 : 0;
  const s = ctx.sum;
  return { fitness: s.gates + s.time + s.progress + s.hold + s.upright + s.spin + crash, terms: { crash: crash } };
}
function descriptor(ctx) { return [ctx.memory.tFinish || ctx.info.duration, ctx.memory.gate || 0]; }
// Genes: the drone-race timid hover tune as the start point, plus lead.
function genome(base) {
  const g = (name, lo, hi, init) => base.genes.push({ name: name, group: "script", min: lo, max: hi, initial: init, sigma: (hi - lo) / 10 });
  g("hover", 0.05, 0.2, 0.1);
  g("kAlt", 0, 0.1, 0.02);
  g("kVs", 0, 0.1, 0.03);
  g("kAtt", 0, 0.01, 0.003);
  g("kRate", 0, 0.003, 0.0006);
  g("kPos", 0, 5, 0.5);
  g("kVel", 0, 10, 2);
  g("kYaw", 0, 0.006, 0.002);
  g("tiltMax", 10, 80, 45);
  g("lead", 0, 15, 0);
  return base;
}
function control(ctx) {
  const G = ctx.genome;
  quad(ctx, { hover: G.get("hover"), kAlt: G.get("kAlt"), kVs: G.get("kVs"), kAtt: G.get("kAtt"), kRate: G.get("kRate"),
    kPos: G.get("kPos"), kVel: G.get("kVel"), kYaw: G.get("kYaw"), tiltMax: G.get("tiltMax") }, aim(ctx), 0);
  if (ctx.memory.gate === undefined) ctx.memory.gate = 0;
}

// --- Quad flight controller (shared by drone-hover / drone-race). Cascade: position -> lean angle -> attitude PD
//     -> motor mixer, plus altitude PD and yaw-rate damping, all in thrust-fraction units (0..1 of static thrust).
//     tgt = offset to the goal (m, world axes); yawSp = yaw-rate setpoint (deg/s).
function quad(ctx, G, tgt, yawSp) {
  const i = ctx.in, m = ctx.memory, dt = ctx.dt;
  const dx = tgt.dx, dy = tgt.dy, dz = tgt.dz;
  // ground velocity from the rate of change of the target offset (there is no velocity sensor), lightly filtered
  const vx = m.pdx === undefined ? 0 : -(dx - m.pdx) / dt, vz = m.pdz === undefined ? 0 : -(dz - m.pdz) / dt;
  m.vx = m.vx === undefined ? 0 : m.vx + (vx - m.vx) * 0.3; m.vz = m.vz === undefined ? 0 : m.vz + (vz - m.vz) * 0.3;
  m.pdx = dx; m.pdz = dz;
  const lim = G.tiltMax;
  const pitchSp = clamp(-(G.kPos * dx - G.kVel * m.vx), -lim, lim);   // nose down to go +x
  const rollSp = clamp(G.kPos * dz - G.kVel * m.vz, -lim, lim);       // roll positive to go +z
  const tilt = Math.min(Math.sqrt(i["att.pitch"] * i["att.pitch"] + i["att.roll"] * i["att.roll"]), 80) * Math.PI / 180;
  const f = (G.hover + G.kAlt * clamp(dy, -10, 10) - G.kVs * i.vs) / Math.max(Math.cos(tilt), 0.3);   // tilt compensation
  const p = G.kAtt * (pitchSp - i["att.pitch"]) - G.kRate * i["rate.pitch"];
  const r = G.kAtt * (rollSp - i["att.roll"]) - G.kRate * i["rate.roll"];
  const y = -G.kYaw * (i["rate.yaw"] - (yawSp || 0));   // speeding up the CW pair (FL, RR) yaws the body to negative rate
  const e = (v) => Math.pow(clamp(v, 0, 1), 1.5);   // thrust fraction -> motor command (static thrust ~ power^2/3)
  ctx.out["Motor FL"] = e(f + p + r + y);
  ctx.out["Motor FR"] = e(f + p - r - y);
  ctx.out["Motor RL"] = e(f - p + r - y);
  ctx.out["Motor RR"] = e(f - p - r + y);
}
